#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while (t--) {        int x, k;        cin >> x >> k;         // Case 1: x is not divisible by k → one jump        if (x % k != 0) {            cout << 1 << "\n";            cout << x << "\n";        }        // Case 2: x is divisible by k → two jumps        else {            cout << 2 << "\n";            cout << 1 << " " << x - 1 << "\n";        }    }    return 0;}